class Product
    private define price as integer;

    method constructor(aPrice as integer)
        this.price <- aPrice;
    endMethod

    public method PriceWithDiscount(percentage as integer) as real
        return this.price - this.price * percentage / 100;
    endMethod
endClass

algorithm ComputeDiscount
    define price as integer;
    define percentage as integer;
    define product as Product;
    read price;
    read percentage;
    product <- new Product(price);
    write product.PriceWithDiscount(percentage);
endAlgorithm
